#include <iostream>
#include <cstring>
class Text{char*p;static int copies;public:Text(const char*s=""):p(new char[std::strlen(s)+1]){std::strcpy(p,s);}Text(const Text&o):p(new char[std::strlen(o.p)+1]){std::strcpy(p,o.p);++copies;std::cout<<"[copy] ";}Text&operator=(const Text&o){if(this!=&o){char*n=new char[std::strlen(o.p)+1];std::strcpy(n,o.p);delete[]p;p=n;}return *this;}~Text(){delete[]p;}Text operator+(const Text&o)const{char*n=new char[std::strlen(p)+std::strlen(o.p)+1];std::strcpy(n,p);std::strcat(n,o.p);Text t(n);delete[]n;return t;}bool operator==(const Text&o)const{return std::strcmp(p,o.p)==0;}bool operator!=(const Text&o)const{return !(*this==o);}friend std::ostream&operator<<(std::ostream&o,const Text&t){return o<<t.p;}static int count(){return copies;}};int Text::copies=0;
int main(){Text a("Hello "),b("C++"),c("!");Text x=a+b+c;std::cout<<x<<" copies="<<Text::count()<<'\n';Text empty;Text y("Longer SMS message");y=y;std::cout<<'['<<empty<<"] "<<(y==y)<<'\n';}
